preferences.cameraJoystick=preferences.cameraJoystick!==false;preferences.joystickDeadzone=Number.isFinite(preferences.joystickDeadzone)?preferences.joystickDeadzone:.12;preferences.cameraSensitivity=Number.isFinite(preferences.cameraSensitivity)?preferences.cameraSensitivity:1;
let cameraAxesV06={x:0,y:0},cameraPointerV06=null,controllerButtonsV06=[];
const cameraStickV06=document.createElement('div');cameraStickV06.id='cameraStickV06';cameraStickV06.setAttribute('role','group');cameraStickV06.setAttribute('aria-label','Camera joystick');cameraStickV06.innerHTML='<div class="cameraStickBaseV06"><span id="cameraKnobV06"></span></div><small>CAMERA</small>';$('bottom').append(cameraStickV06);
function resetCameraStickV06(){cameraAxesV06={x:0,y:0};cameraPointerV06=null;$('cameraKnobV06').style.transform='translate(-50%,-50%)';}
function setCameraStickV06(x,y){const r=cameraStickV06.getBoundingClientRect(),dx=x-r.left-r.width/2,dy=y-r.top-r.height/2,max=r.width*.27,len=Math.hypot(dx,dy),scale=Math.min(1,max/Math.max(.01,len)),dead=preferences.joystickDeadzone*max;cameraAxesV06={x:len<dead?0:dx*scale/max,y:len<dead?0:dy*scale/max};$('cameraKnobV06').style.transform=`translate(calc(-50% + ${dx*scale}px),calc(-50% + ${dy*scale}px))`;}
cameraStickV06.addEventListener('pointerdown',e=>{if(paused||activeModal||!usesPolished3D())return;e.preventDefault();cameraPointerV06=e.pointerId;cameraStickV06.setPointerCapture(e.pointerId);setCameraStickV06(e.clientX,e.clientY)});
cameraStickV06.addEventListener('pointermove',e=>{if(e.pointerId===cameraPointerV06){e.preventDefault();setCameraStickV06(e.clientX,e.clientY)}});
