setJoy=function(x,y){const r=joystick.getBoundingClientRect(),dx=x-r.left-r.width/2,dy=y-r.top-r.height/2,max=r.width*.3,len=Math.hypot(dx,dy),ratio=Math.min(1,max/Math.max(.01,len)),px=dx*ratio,py=dy*ratio,dead=max*preferences.joystickDeadzone;joyX=len<dead?0:px/max;joyY=len<dead?0:py/max;knob.style.transform=`translate(calc(-50% + ${px}px),calc(-50% + ${py}px))`;knob.classList.toggle('active',!!(joyX||joyY));};
function syncControlPreferencesV06(){cameraStickV06.classList.toggle('hidden',!preferences.cameraJoystick);document.documentElement.style.setProperty('--movement-stick-v06',Math.min(state?.controlSize||preferences.controlSize||156,innerWidth<650?innerWidth*.37:170)+'px');}
const applyBeforeControlsV06=applyPreferences;
