document.addEventListener('input',e=>{const key=e.target.dataset.controlV06;if(!key)return;preferences[key]=e.target.type==='checkbox'?e.target.checked:Number(e.target.value)/100;storePreferences();syncControlPreferencesV06();});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&activeModal){e.preventDefault();e.stopImmediatePropagation();if(!$('modal').classList.contains('hidden'))hideModal();else if(!$('interiorOverlay').classList.contains('hidden'))leaveInterior();return;}if(e.target.matches('input,select,textarea,[contenteditable="true"]')){if(e.key!=='Tab')e.stopImmediatePropagation();return;}if(e.key===' '&&!paused&&!activeModal){e.preventDefault();e.stopImmediatePropagation();useEquippedToolV06();}},true);
